        cardsContainer.innerHTML = '';
        if (about.cards) {
            about.cards.forEach(card => {
                const div = document.createElement('div');
                div.className = 'about-card';
                div.innerHTML = `
                    <h3>${card.title}</h3>
                    <p>${card.text}</p>
                `;
                cardsContainer.appendChild(div);
            });
        }
    }

