.preview { max-width: 100px; margin-top: 10px; }
.hero-badges { margin-top: 20px; }
.badge-item { display: flex; align-items: center; margin-bottom: 10px; }
.badge-item input { margin-left: 10px; }
.album-photos-list li { display: flex; align-items: center; margin-bottom: 5px; }
.album-photos-list input { flex-grow: 1; margin-right: 10px; }
.file-input-container { position: relative; margin-bottom: 10px; }
.file-input-button { background: var(--gold); color: #fff; border: none; padding: 8px 12px; border-radius: 3px; cursor: pointer; font-size: 12px; }
.file-input-button:hover { background: var(--gold-hover); color: #fff; }
.file-input-hidden { position: absolute; left: -9999px; }
.current-file { font-size: 12px; color: var(--muted); margin-top: 5px; }
.photo-item { display: flex; align-items: center; margin-bottom: 10px; padding: 10px; background: var(--card); border: 1px solid var(--line); border-radius: 5px; }
.photo-preview { width: 80px; height: 60px; object-fit: cover; margin-right: 10px; border-radius: 3px; }

